use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The hosts this node's HTTPClient capability is scoped to. Requests outside
/// this set would trap at the boundary, so they are recorded as failures
/// instead of being attempted.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the lowercase host from an http(s) URL, or None if the URL is not
/// a well-formed http(s) URL.
fn host_of(url: &str) -> Option<String> {
    let url = url.trim();
    let (scheme, rest) = url.split_once("://")?;
    let scheme = scheme.to_ascii_lowercase();
    if scheme != "https" && scheme != "http" {
        return None;
    }
    let authority_end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..authority_end];
    // Drop any userinfo.
    let host_port = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };
    // Bracketed IPv6 literals are never on the allowlist.
    if host_port.starts_with('[') {
        return None;
    }
    let host = match host_port.split_once(':') {
        Some((h, _)) => h,
        None => host_port,
    };
    let host = host.trim_end_matches('.').to_ascii_lowercase();
    if host.is_empty() {
        None
    } else {
        Some(host)
    }
}

fn is_allowed(url: &str) -> bool {
    match host_of(url) {
        Some(h) => ALLOWED_HOSTS.iter().any(|a| *a == h),
        None => false,
    }
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            if !is_allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: String::from("url is not an http(s) url on an allowed host"),
                });
                continue;
            }
            match http_client::fetch(url.trim()) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
```

